import { useState } from "react";
export default function Arraystate() {
  const [devicse, setdvice] = useState("");
  const [arrdvices, setarrdvis] = useState(["14Pro", "15Pro", "16Pro"]);
  const dviselist = arrdvices.map((d) => {
    return <li>{d}</li>;
  });
  return (
    <div className="list">
      {dviselist}
      <></>
      <input
        value={devicse}
        onChange={(d) => {
          setdvice(d.target.value);
        }}
      ></input>

    </div>
  );
}
